import{_ as l,l as r,o as s,c as m,v as n,p,x as o,d as e,i as f,S as d,b as t}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"softmax 替代与 softpick","description":"","frontmatter":{"title":"softmax 替代与 softpick","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/softmax-alternatives.md","filePath":"llm/softmax-alternatives.md","lastUpdated":1789023840000}'),x={name:"llm/softmax-alternatives.md"};function h(c,a,E,u,A,S){const i=r("Mermaid");return s(),m("div",null,[a[1]||(a[1]=n('<h1 id="softmax-替代与-softpick" tabindex="-1">softmax 替代与 softpick <a class="header-anchor" href="#softmax-替代与-softpick" aria-label="Permalink to &quot;softmax 替代与 softpick&quot;">​</a></h1><div class="epigraph"><p>Softmax 把权重钉在单纯形上；若需要稀疏、需要可关断、或不需要概率解释，就该换投影，而不是再叠一个门。</p><footer>—— Martins &amp; Astudillo, From Softmax to Sparsemax, ICML 2016；离开单纯形的路线上还有 softpick 一类可关断算子</footer></div><p><a href="/llm/sigmoid-attention">上一课</a>用逐点 sigmoid 离开单纯形。<a href="/llm/gated-attention">门控注意力</a>则留在 softmax 里事后调幅。本课把中间地带收齐：仍想要<strong>行内竞争</strong>，但不想要 softmax 的严格正、满支撑。Sparsemax、entmax 把一部分键精确打到 0；softpick 一类算子进一步取消「必须是分布」。后课转向 KV 跨层共享，默认你已知道「归一化是可选模块」，不再把 softmax 当成注意力定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Softmax 输出 \\(p_i\\gt 0\\) 且 \\(\\sum p_i=1\\)。长序列上绝大多数键应真正不贡献，尾部的正质量却仍在稀释、仍在占存储。Sigmoid 能全关，却失去竞争，尺度要另补。缺口是：<strong>保留 argmax 式的相对比较，同时允许精确零</strong>，或允许和不为 1。</p><p>Martins 与 Astudillo 的 sparsemax 是把向量投影到单纯形，落在面上的坐标可以为 0。Entmax 在 softmax 与 sparsemax 之间用一个 \\(\\alpha\\) 插值。近期的 softpick 把「挑出若干正贡献、其余为零、不做单纯形归一」当成核，服务的是可关断加稀疏，而不是概率。</p><p><span class="marginnote">「Attention is off by one」把分母写成 \\(1+\\sum e^{z}\\)，等价于多一个永不出现的键。它仍在指数族里，本课不把它当成另一族替代，只提醒：分母微变也会改变汇的强度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Sparsemax：\\(\\mathrm{sparsemax}(z)=\\mathrm{argmin}_{p\\in\\Delta}\\|p-z\\|^2\\)，阈值以下的坐标为 0，其余平移后和为 1。Entmax\\(_\\alpha\\) 用 Tsallis 熵， \\(\\alpha=1\\) 退回 softmax，\\(\\alpha=2\\) 即 sparsemax。二者都能接在 \\(QK^\\top/\\sqrt{d_k}\\) 之后，掩码仍是非法位置先置 \\(-\\infty\\) 或移出投影。</p><p>Softpick 不把输出约束在 \\(\\Delta\\) 上：先用光滑函数挑出正向贡献，再按需归一或直接乘值。实现上要自己管输出尺度，思想与 sigmoid 更近，但挑的过程仍看行内相对大小，不是完全逐点。</p><h3 id="梯度与核融合" tabindex="-1">梯度与核融合 <a class="header-anchor" href="#梯度与核融合" aria-label="Permalink to &quot;梯度与核融合&quot;">​</a></h3><p>Softmax 的 Jacobian 有闭式 $ \\mathrm{diag}(p)-pp^\\top$。Sparsemax 只在支撑集上类似仿射，支撑随输入变，核要动态掩码。这就是为何生产级解码器仍默认 softmax：不是表达力最优，而是分块核、反向、混合精度都已打磨。替代函数若不能进 Flash 一类核，长上下文先不可用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>精确零让 KV 在数学上可以跳过——若实现真去跳。多数框架仍算满矩阵，稀疏只发生在数值里，加速不明显。表达上，稀疏竞争恢复了「少数键拿走全部质量」，比 sigmoid 更像检索；比 softmax 更不像「每个键都沾一点」。Entmax 的 \\(\\alpha\\) 是在稀释与硬选择之间滑动的旋钮，训练中可学或固定。</p><p>和不为 1 时，残差写入幅度随通过质量变，注意力汇可以消失，也回到上一课的范数问题。课序上应先问要不要单纯形，再问支不支持精确零。</p><p><span class="marginnote">头与头可以不同核，但几乎没人这么做：检查点、核、超参都会裂成按头的配置。替代发生在整层，而不是按头点菜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在已经收敛的 softmax 模型上只换激活来「升级」。单纯形上的尖峰是训出来的，换投影会把已有头的功能打乱。评测若只看困惑度，softmax 通常仍赢；看长上下文噪声、sink、可关断，替代才有理由。下一课开始省 KV，默认层内仍是 softmax，除非显式声明。</p>',18)),(s(),p(d,null,{default:o(()=>[f(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%20logits%22%5D%20--%3E%20SM%5B%22Softmax%20%E6%BB%A1%E6%94%AF%E6%92%91%22%5D%0A%20%20Z%20--%3E%20SP%5B%22Sparsemax%20%E7%B2%BE%E7%A1%AE%E9%9B%B6%22%5D%0A%20%20Z%20--%3E%20SG%5B%22Sigmoid%20%E6%97%A0%E7%AB%9E%E4%BA%89%22%5D%0A%20%20Z%20--%3E%20PK%5B%22Softpick%20%E5%8F%AF%E5%85%B3%E6%96%AD%22%5D%0A%20%20SM%20--%3E%20V%5B%22%E4%B9%98%E5%80%BC%22%5D%0A%20%20SP%20--%3E%20V%0A%20%20SG%20--%3E%20V%0A%20%20PK%20--%3E%20V%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t("h2",{id:"小结",tabindex:"-1"},[e("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=t("ul",null,[t("li",null,"替代 softmax 的动机是稀疏、可关断或放弃概率解释，不是重推 SDPA。"),t("li",null,"Sparsemax / entmax 保留单纯形竞争并允许精确零；sigmoid / softpick 离开分布。"),t("li",null,"生产默认仍是 softmax，因为核与稳定性；数值稀疏不等于核稀疏。"),t("li",null,"换核不能当已有检查点的热修补。"),t("li",null,"出处：Martins & Astudillo, ICML 2016；sigmoid 见上一课。")],-1))])}const B=l(x,[["render",h]]);export{g as __pageData,B as default};
